async function importPreview(c){const i=c.input,plan=await row(c.t,'plan',i.plan_id);if(!same(plan.group_id,c.group))missing();await planAccess(c,plan,'import');const kind=i.kind;if(!['org_input','bonus_month'].includes(kind))bad('当前原生Excel入口支持组织指标与奖金月度基准；历史成绩须保留原始系统来源，不能冒作本期评分');const {readNamedWorkbook,columnName}=await import('./customer-performance-import.mjs');const raw=Buffer.from(text(i.content_base64,'Excel内容',20,4500000),'base64'),book=readNamedWorkbook(raw);if(!book||book.errors.length||book.formula_count||book.external_formula_count||book.external_relationship_count)bad('导入须为无公式、无外部链接的已确认值XLSX');const sheet=book.sheets.find(s=>s.name===i.sheet_name)??book.sheets.find(s=>!s.hidden);if(!sheet||sheet.max_row<2||sheet.max_row>1001)bad('导入需1至1000行数据');const headers=Array.from({length:sheet.max_column},(_,x)=>String(sheet.cells.get(columnName(x+1)+'1')?.value??'').trim()),allowed=kind==='org_input'?['id','expected_revision','company_id','period','metric_code','values_json','evidence_ref']:['id','expected_revision','target_id','period','attainment','bonus_base','base_unit','eligibility_weight','currency','evidence_ref'],seen=new Set();for(const h of headers)if(!allowed.includes(h)||seen.has(h))bad('导入列须使用模板字段且不可重复：'+allowed.join('、'));else seen.add(h);const parsed=[],issues=[];for(let n=2;n<=sheet.max_row;n++){const record={plan_id:plan.id};for(let col=0;col<headers.length;col++){const cell=sheet.cells.get(columnName(col+1)+n);record[headers[col]]=cell?.value==null?'':cell.cell_type==='n'?String(cell.raw_value_text):String(cell.value);}if(Object.values(record).every(v=>v===''))continue;try{record.period=period(record.period);if(kind==='org_input')record.values=JSON.parse(record.values_json);else{const t=await target(c,record.target_id,'import','perf_bonus',['bonus_base','attainment','eligibility_weight']);if(!same(t.plan_id,plan.id))bad('奖金月度目标不属于当前计划');record.target_revision=t.revision;}if(record.id==='')delete record.id;if(record.expected_revision==='')delete record.expected_revision;await c.t.query('SAVEPOINT performance_import_row');try{await inputSave({...c,input:record},kind);await c.t.query('ROLLBACK TO SAVEPOINT performance_import_row');await c.t.query('RELEASE SAVEPOINT performance_import_row');}catch(e){await c.t.query('ROLLBACK TO SAVEPOINT performance_import_row');await c.t.query('RELEASE SAVEPOINT performance_import_row');throw e;}parsed.push({row_number:n,input:record});}catch(e){issues.push({row:n,code:e.code??'E_TY_ARGUMENT',message:String(e.message).slice(0,600)});}}const namespace=text(i.namespace,'导入命名空间',4,100),sourceHash=hash({plan_id:plan.id,kind,bytes:raw.toString('base64')}),existing=await one(c.t,'SELECT * FROM ty_pr_import_batch WHERE group_id=$1 AND namespace=$2 AND kind=$3 AND source_hash=$4',[c.group,namespace,kind,sourceHash]);if(existing)return{kind:'import',id:existing.id};const batch=await one(c.t,'INSERT INTO ty_pr_import_batch(group_id,plan_id,kind,namespace,filename,source_hash,parsed_rows,issues,status,created_by)VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8::jsonb,$9,$10)RETURNING *',[c.group,plan.id,kind,namespace,text(i.filename,'文件名',1,240),sourceHash,json(parsed),json(issues),issues.length?'invalid':'validated',c.userId]);await event(c,'import',batch.id,'import.previewed',null,{kind,rows:parsed.length,issues:issues.length});return{kind:'import',id:batch.id};}
async function importCommit(c){const batch=await row(c.t,'import',c.input.id,true);if(!same(batch.group_id,c.group))missing();const p=await row(c.t,'plan',batch.plan_id);await planAccess(c,p,'import');revision(batch,c.input.expected_revision);if(batch.status!=='validated'||batch.issues.length)conflict('导入预检有阻断或已办理，须先核对');for(const r of batch.parsed_rows){if(r.input.target_id){const t=await row(c.t,'target',r.input.target_id);if(Number(t.revision)!==Number(r.input.target_revision))conflict('导入所依据参评目标已变，请重新预检');}await inputSave({...c,input:r.input},batch.kind);}await c.t.query("UPDATE ty_pr_import_batch SET status='applied',revision=revision+1 WHERE id=$1",[batch.id]);await event(c,'import',batch.id,'import.applied',null,{rows:batch.parsed_rows.length,authoritative_state:'draft_requires_independent_verification'});return{kind:'import',id:batch.id};}
export async function exportReport(t,{userId,input={}}){const c=await ctx(t,userId,input),view=input.view??'results';if(!['results','targets','bonus','bonus_months','org_inputs'].includes(view))bad('该绩效视图暂不支持Excel导出');const rows=[];let page=1,total=0;do{const part=await queryWorkspace(t,{userId,input:{...input,page,page_size:100}});total=part.total;for(const r of part.rows){const res=c.self?'perf_self':view==='bonus'||view==='bonus_months'?'perf_bonus':view==='results'?'perf_review':'perf_cycle';await access(c,res,'export',{group_id:c.group,...r});const value=await project(c,res,{group_id:c.group,...r},'export');if(value)rows.push(value);}page++;if(total>100000)bad('结果超过十万行，请收窄筛选范围');}while(rows.length<total&&(page-1)*100<total);const keys=['person_number','full_name','company_id','employment_id','plan_name','period','version','status','score','grade','algorithm','target_amount','algorithm_a_amount','algorithm_b_amount','currency','attainment','bonus_base','base_unit','eligibility_weight'],labels={person_number:'永久工号',full_name:'姓名',company_id:'公司引用',employment_id:'真实关系引用',plan_name:'绩效计划',period:'期间',version:'版本',status:'状态',score:'成绩',grade:'等级',algorithm:'正式算法',target_amount:'累计奖金目标',algorithm_a_amount:'算法A试算',algorithm_b_amount:'算法B试算',currency:'币种',attainment:'达成率',bonus_base:'奖金基准',base_unit:'基准单位',eligibility_weight:'资格比例'},columns=keys.filter(k=>rows.some(r=>Object.hasOwn(r,k))).map(k=>({key:k,label:labels[k],width:20}));const{writeXlsx}=await import('../xlsx-write.mjs'),content=writeXlsx({sheetName:'绩效授权导出',columns:columns.length?columns:[{key:'status',label:'无受权数据'}],rows});return{filename:`天意HR_绩效_${view}.xlsx`,mime:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',content_base64:content.toString('base64'),row_count:rows.length,applied_filters:true,permission_scope:'current'};}
export async function personHistory(t,{userId,input}){return queryWorkspace(t,{userId,input:{...input,view:'results',person_id:id(input.person_id)}});}
export async function performanceWorkflowSource(t,{userId,id:key,forSubmission=true}){const r=await row(t,'result',key),root=await one(t,'SELECT * FROM ty_pr_result_root WHERE id=$1',[r.root_id]),c=await ctx(t,userId,{group_id:root.group_id});if(forSubmission)await access(c,'perf_cycle','submit',root,['scores','sources','status']);else if(!await can(c,'perf_review','read',root,['scores','sources','status']))await access(c,'perf_cycle','read',root,['scores','sources','status']);if(forSubmission&&(r.status!=='proposed'||!same(r.created_by,userId)))deny('只能提交本人制单且未办理的逐人成绩意图');const snapshot={id:r.id,root_id:r.root_id,target_id:r.target_id,version:r.version,score:String(r.score),grade:r.grade,source_hash:r.source_hash,expected_head_revision:r.expected_head_revision,expected_approved_id:r.expected_approved_id};return{id:r.id,group_id:root.group_id,company_id:root.company_id,person_id:root.person_id,hash:hash(snapshot),original_requester_id:r.created_by,safe_title:'绩效成绩核准',safe_values:{subject_id:r.id,result_id:r.id,group_id:root.group_id,company_id:root.company_id},snapshot};}
export async function assertPerformanceApprovalAccess(t,{userId,id:key}){const r=await row(t,'result',key),root=await one(t,'SELECT * FROM ty_pr_result_root WHERE id=$1',[r.root_id]),c=await ctx(t,userId,{group_id:root.group_id});await access(c,'perf_review','approve',root,['scores','sources','status']);await independent(c,root,r.created_by);if(r.status!=='proposed'&&r.status!=='approved')conflict('成绩意图已撤回或驳回，不能继续核准');return{result:r,root};}
export async function executeApprovedPerformance(t,{userId,input}){const r=await row(t,'result',input.id),root=await one(t,'SELECT * FROM ty_pr_result_root WHERE id=$1',[r.root_id]),source=await performanceWorkflowSource(t,{userId,id:r.id,forSubmission:false}),flow=await import('./platform-workflow.mjs'),receipt=await flow.verifyApprovalReceipt(t,{userId,instanceId:input.approval_receipt_id,subjectType:'performance_result',subjectId:String(r.id),sourceHash:source.hash}),c=await ctx(t,userId,{group_id:root.group_id,id:r.id,expected_revision:r.revision,reason:'统一审批流实际核准:'+receipt.instance_id});await assertPerformanceApprovalAccess(t,{userId:receipt.approved_by,id:r.id});return command(t,{userId,groupId:root.group_id,operation:'performance.workflow.execute',operationId:'PERFORMANCE-WORKFLOW:'+receipt.instance_id,input:{instance_id:receipt.instance_id,result_id:r.id,source_hash:source.hash},execute:async()=>{await t.query('SAVEPOINT performance_domain_apply');try{const out=await resultDecide(c,true,receipt);await t.query("UPDATE ty_workflow_instance SET business_state='applied',revision=revision+1 WHERE id=$1",[receipt.instance_id]);await t.query('RELEASE SAVEPOINT performance_domain_apply');return out;}catch(e){await t.query('ROLLBACK TO SAVEPOINT performance_domain_apply');await t.query('RELEASE SAVEPOINT performance_domain_apply');if(!['23514','40001','E_TY_CONFLICT'].includes(e.code)&&!String(e.message).startsWith('E_TY_CONFLICT:'))throw e;await t.query("UPDATE ty_workflow_instance SET business_state='blocked',revision=revision+1 WHERE id=$1",[receipt.instance_id]);await emit(t,c.group,'performance:workflow:'+receipt.instance_id+':blocked','performance.execution.needs_review',{instance_id:receipt.instance_id,result_id:r.id,domain_applied:false});return{kind:'blocked',id:r.id,blocked:true};}},project:async out=>out.blocked?{blocked:true,source_changed:true,domain_applied:false,result_id:out.id}:{domain_applied:true,result_id:out.id,execution_actor:userId,approved_by:receipt.approved_by}});}
export async function rejectPerformanceWorkflow(t,{userId,instance}){const source=await performanceWorkflowSource(t,{userId,id:instance.subject_id,forSubmission:false}),actual=await one(t,'SELECT * FROM ty_workflow_instance WHERE id=$1 FOR UPDATE',[instance.id]);if(!actual||actual.status!=='rejected'||!same(actual.last_approver_id,userId)||actual.source_hash!==source.hash||!same(actual.applicant_id,source.original_requester_id)||!await one(t,"SELECT 1 FROM ty_workflow_task WHERE instance_id=$1 AND approver_id=$2 AND status='rejected'",[actual.id,userId]))deny('不是当前操作人的真实拒绝回执');await assertPerformanceApprovalAccess(t,{userId,id:source.id});const r=await row(t,'result',source.id),c=await ctx(t,userId,{group_id:source.group_id,id:r.id,expected_revision:r.revision,reason:'统一审批流真实驳回:'+instance.id});await resultDecide(c,false);await t.query("UPDATE ty_workflow_instance SET business_state='applied'WHERE id=$1",[instance.id]);return{domain_rejected:true,result_id:r.id};}
export async function cancelPerformanceWorkflow(t,{userId,instance}){const source=await performanceWorkflowSource(t,{userId,id:instance.subject_id,forSubmission:false}),r=await row(t,'result',source.id,true);if(!same(userId,source.original_requester_id)||instance.source_hash!==source.hash||r.status!=='proposed')deny('只能撤回本人同一未办理成绩意图');await t.query("UPDATE ty_pr_result_version SET status='cancelled',revision=revision+1 WHERE id=$1",[r.id]);return{domain_cancelled:true,result_id:r.id};}
